import { PDFDocument, StandardFonts, rgb, type PDFFont, type PDFPage } from 'pdf-lib';
import type { Invoice } from '../src/shared/types.js';

export class CloudPdfError extends Error {
  readonly status=422;
  readonly code='PDF_TEXT_UNSUPPORTED';
}

const money=(cents:number)=>new Intl.NumberFormat('de-DE',{minimumFractionDigits:2,maximumFractionDigits:2}).format(cents/100)+' EUR';
const date=(value:string)=>value.split('-').reverse().join('.');
// Layout separators generated by the domain are represented with printable PDF-standard glyphs.
const printable=(value:string)=>value.replace(/\u2192/g,' -> ').replace(/[\u202f\u00a0]/g,' ').replace(/\u2011/g,'-');

/** Portable Worker PDF: no filesystem, process globals, streams or SQLite. Original bytes are archived by CloudStore. */
export async function renderCloudInvoicePdf(invoice:Invoice,referenceNumber?:string):Promise<Uint8Array>{
  const pdf=await PDFDocument.create();
  pdf.setTitle(`TaxiDTA Testrechnung ${invoice.number}`);
  pdf.setAuthor('Insel Taxi · Testbetrieb');
  pdf.setSubject('Synthetischer Testbetrieb; keine fachliche oder steuerliche Freigabe');
  pdf.setCreationDate(new Date(invoice.createdAt));
  const regular=await pdf.embedFont(StandardFonts.Helvetica);
  const bold=await pdf.embedFont(StandardFonts.HelveticaBold);
  let page!:PDFPage;let y=0;
  const left=44,right=551,bottom=72;
  const text=(value:string,x:number,at:number,size=9,font:PDFFont=regular)=>{
    const content=printable(value);
    try{font.encodeText(content);}catch{throw new CloudPdfError('Ein Zeichen lässt sich mit der eingebauten PDF-Schrift nicht darstellen. Bitte für diesen synthetischen Test lateinische Schrift verwenden. Es wurde keine Rechnung ausgestellt.');}
    page.drawText(content,{x,y:at,size,font,color:rgb(.08,.16,.12)});
  };
  const wrapped=(value:string,width:number,size:number,font:PDFFont=regular):string[]=>{
    const rows:string[]=[];
    for(const paragraph of printable(value).split(/\r\n|[\r\n\u2028\u2029]/u)){
      if(!paragraph){rows.push('');continue;}
      let row='';
      // Character wrapping also handles unusually long references without clipping or dropping text.
      for(const character of paragraph){
        const candidate=row+character;
        let measured:number;
        try{measured=font.widthOfTextAtSize(candidate,size);}catch{throw new CloudPdfError('Ein Zeichen lässt sich mit der eingebauten PDF-Schrift nicht darstellen. Bitte für diesen synthetischen Test lateinische Schrift verwenden. Es wurde keine Rechnung ausgestellt.');}
        if(row&&measured>width){rows.push(row);row=character;}else row=candidate;
      }
      rows.push(row);
    }
    return rows;
  };
  const newPage=()=>{
    page=pdf.addPage([595.28,841.89]);
    text('TaxiDTA',left,798,23,bold);
    text('PRIVATER CLOUD-TEST · NUR ERFUNDENE DATEN',left,778,8);
    y=752;
  };
  const ensure=(height:number)=>{if(y-height<bottom)newPage();};
  const block=(value:string,width=right-left,size=9,font:PDFFont=regular)=>{
    for(const row of wrapped(value,width,size,font)){ensure(size+5);text(row,left,y,size,font);y-=size+5;}
  };
  newPage();
  block('Insel Taxi · Testbetrieb',right-left,11,bold);
  block('Test-Rechnungsaussteller · keine Bankverbindung');y-=18;
  block(invoice.customerSnapshot.name,340,11,bold);
  block(invoice.customerSnapshot.address,340);y-=20;
  ensure(104);
  block(invoice.originalInvoiceId?'Stornorechnung':'Testrechnung',right-left,20,bold);
  block(`Nummer: ${invoice.number}    Rechnungsdatum: ${date(invoice.issuedAt)}`);
  block(`${invoice.dueAtVerified===false?'Wiedervorlage (Demo)':'Fällig'}: ${date(invoice.dueAt)}`);
  if(invoice.originalInvoiceId)block(`Bezug: ${referenceNumber??invoice.originalInvoiceId}`);
  y-=12;
  const header=()=>{
    ensure(36);
    page.drawRectangle({x:left,y:y-8,width:right-left,height:23,color:rgb(.93,.96,.94)});
    text('Leistung / Datum',left+5,y,8,bold);
    text('USt.',365,y,8,bold);text('Netto',412,y,8,bold);text('Brutto',490,y,8,bold);y-=27;
  };
  header();
  for(const line of invoice.lines){
    const description=wrapped(`${line.description}\n${date(line.serviceDate)}`,306,9);
    for(let index=0;index<description.length;index++){
      if(y-14<bottom){newPage();header();}
      text(description[index],left+5,y,9);
      if(index===0){
        text(`${line.taxRate} %`,365,y,8);
        const net=money(line.netCents),gross=money(line.grossCents);
        text(net,461-regular.widthOfTextAtSize(net,8),y,8);
        text(gross,right-regular.widthOfTextAtSize(gross,8),y,8);
      }
      y-=13;
    }
    y-=9;page.drawLine({start:{x:left,y:y+3},end:{x:right,y:y+3},thickness:.4,color:rgb(.8,.86,.82)});
  }
  const groups=new Map<number,{net:number,tax:number}>();
  for(const line of invoice.lines){const group=groups.get(line.taxRate)??{net:0,tax:0};group.net+=line.netCents;group.tax+=line.taxCents;groups.set(line.taxRate,group);}
  ensure(groups.size*34+120);y-=10;
  for(const[rate,group]of groups){block(`Netto (${rate} % USt.): ${money(group.net)}`);block(`Umsatzsteuer ${rate} %: ${money(group.tax)}`);}
  block(`Gesamtbetrag: ${money(invoice.grossCents)}`,right-left,13,bold);y-=12;
  block(invoice.originalInvoiceId?'Storno mit unveränderlichem Bezug zur ursprünglichen Testrechnung.':invoice.dueAtVerified===false?'Vertragliche Kassenfrist ungeprüft. Das Datum ist nur eine Demo-Wiedervorlage. Kein Geld überweisen.':'Zahlungsziel: 28 Kalendertage. Kein Geld überweisen: Dies ist ein Testdokument.');
  const pages=pdf.getPages();
  for(let index=0;index<pages.length;index++){
    page=pages[index];
    text('TESTDOKUMENT – KEINE STEUERLICHE ODER FACHLICHE FREIGABE',left,42,8);
    text(`${invoice.number} · Seite ${index+1} / ${pages.length}`,left,28,8);
  }
  return pdf.save();
}
